                    _jd = (r2.get("kai") or {}).get("judge") if isinstance(r2.get("kai"), dict) else None
                    if isinstance(_jd, dict) and _jd.get("tier") == "keep" and _jd.get("name"):
                        _kn = str(_jd["name"]).strip()
